	private static StatementPattern anchor(TupleExpr root) {
		List<StatementPattern> result = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				if (pattern.getPredicateVar().hasValue()
						&& ID_SHORT.equals(pattern.getPredicateVar().getValue().stringValue())
						&& pattern.getObjectVar().getValue()instanceof Literal literal
						&& "ratedPower".equals(literal.getLabel())) {
					result.add(pattern);
				}
			}
		});
		assertEquals(1, result.size(), "COVERAGE_PREREQUISITE: actual complete query has its one lexical anchor");
		return result.getFirst();
	}

	private static long countPattern(SailDatasetTripleTermSource source, IRI predicate, Value object) {
		long count = 0;
		try (var rows = source.getStatements(null, predicate, object)) {
			while (rows.hasNext()) {
				rows.next();
				count++;
			}
		}
		return count;
	}

	private static long countPlan(DefaultEvaluationStrategy strategy, TupleExpr plan) {
		long count = 0;
		try (var rows = strategy.precompile(new QueryRoot(plan.clone())).evaluate(EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				rows.next();
				count++;
			}
		}
		return count;
	}

	private static void restore(String name, String previous) {
		if (previous == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, previous);
		}
	}

	private record NativeInput(Value value, long id, ValueStore.ReadSnapshot snapshot, boolean mappedLeaf,
			List<String> plannerStack) {
	}

	private static final class ProbeValues extends ValueStore {
		final ThreadLocal<ReadSnapshot> currentPin = new ThreadLocal<>();
		final List<NativeInput> inputs = new ArrayList<>();
		boolean plannerCall;

		ProbeValues(File directory, StoreProperties properties, LmdbStoreConfig config) throws IOException {
			super(directory, properties, config);
		}

		@Override
		SailClosable pinQueryPlanningReads(ReadSnapshot snapshot) {
			SailClosable delegate = super.pinQueryPlanningReads(snapshot);
			ReadSnapshot previous = currentPin.get();
			currentPin.set(snapshot);
			return () -> {
				try {
					delegate.close();
				} finally {
					if (previous == null) {
						currentPin.remove();
					} else {
						currentPin.set(previous);
					}
				}
			};
		}

		@Override
		long getStatementId(ReadSnapshot snapshot, Value value) throws IOException {
			long id = super.getStatementId(snapshot, value);
			if (plannerCall && (ID_SHORT.equals(value.stringValue())
					|| value instanceof Literal literal && "ratedPower".equals(literal.getLabel()))) {
				// Observe one actual mapped-leaf resolution per lexical input; no ID publication or dictionary writes.
				boolean alreadyObserved = inputs.stream()
						.anyMatch(input -> input.mappedLeaf()
								&& input.snapshot() == snapshot && input.value().equals(value));
				if (!alreadyObserved) {
					List<String> stack = StackWalker.getInstance()
							.walk(frames -> frames
									.map(frame -> frame.getClassName() + ":" + frame.getMethodName())
									.toList());
					boolean mapped = stack.contains(LmdbPackedCostModel.class.getName() + ":mappedLeafEstimate");
					if (mapped) {
						inputs.add(new NativeInput(value, id, snapshot, true, stack));
					}
				}
			}
			return id;
		}
	}

	private static final class ProbeStore extends LmdbStore {
		ProbeValues values;
		int effectiveBulkOperationSize;

		ProbeStore(File directory) {
			super(directory, new LmdbStoreConfig("spoc,ospc,psoc"));
		}

		ProbeStore(File directory, int bulkOperationSize) {
			super(directory, new LmdbStoreConfig("spoc,ospc,psoc").setBulkOperationSize(bulkOperationSize));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			effectiveBulkOperationSize = config.getBulkOperationSize();
			return new LmdbSailStore(directory, properties, config, sketches,
					(d, p, c) -> {
						values = new ProbeValues(d, p, c);
						return values;
					},
					(d, p, c, v) -> new TripleStore(d, p, c, v));
		}
	}
